window.kbPageData["views/entry/k-335321b0fefa406d"] = {"key":"entry/k-335321b0fefa406d","state":{"route":"entry/k-335321b0fefa406d"},"node":{"id":"k-335321b0fefa406d","mode":"k","title":"三个互异正整数的和的上界","type":"原理与机制","domain":"数学","reading":"","intro":"","priority":100,"aliases":["最大值为x的三个互异正整数之和至多为3x−3"],"qs":["江苏 2025 B类 行测#66"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"三个互不相同的正整数中，若最大数为x，则三数之和至多为3x−3。其余两数分别为x−1和x−2时取到上界。","review":{"definition":"三个互不相同的正整数中，若最大数为x，则三数之和至多为3x−3。其余两数分别为x−1和x−2时取到上界。","explanation":"另外两束各少于最大束，枝数又互不相同，因此至多分别为x−1和x−2。由每8枝余3、每9枝余5可得总数至少为59枝，所以3x−3≥59，得x至少为21。取最小可行总数59枝，分成18、20、21枝即可达到这个下界。","references":[],"evidence":"3束玫瑰花枝数各不相同","disposition":"独立词条","basis":"据原题和解析编释。"}},"questions":{"江苏 2025 B类 行测#66":{"paper":"江苏 2025 B类 行测","n":66,"mod":"数量关系","src":["91e0d9fd02ca7ec6d61f.pdf",13],"asrc":["f2ff67a0f2a2f7e8e926.pdf",21],"card":"1adf49e0fd4d623a742c02e8","links":[{"id":"k-335321b0fefa406d","role":"解题依据","why":"另外两数至多为x−1和x−2，因此用三数和的上界反推最大一束的下界。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-335321b0fefa406d":[["江苏 2025 B类 行测#66"]]}};
